export interface ConnectorConfig {
  datadogApiKey: string
  datadogAppKey: string
  datadogSite: string
  fetch?: typeof fetch
}

export interface MailchimpRetryPayload {
  response_status: number
  retry_count: number
  final_response: {
    type: string
    title: string
    status: number
    detail: string
  }
  retry_after_header?: string
}

export interface DatadogEventResult {
  id: string
}

export async function handle(
  payload: MailchimpRetryPayload,
  config: ConnectorConfig
): Promise<DatadogEventResult> {
  if (payload.response_status === undefined || payload.response_status === null) {
    throw new Error('Missing required field: response_status')
  }
  if (payload.retry_count === undefined || payload.retry_count === null) {
    throw new Error('Missing required field: retry_count')
  }
  if (!payload.final_response) {
    throw new Error('Missing required field: final_response')
  }

  const status = payload.response_status === 429 && payload.retry_count >= 3
    ? 'retry_exhausted'
    : 'error'

  const tags = [
    `retry_count:${payload.retry_count}`,
    ...(payload.retry_after_header ? [`retry_after:${payload.retry_after_header}`] : [])
  ]

  const event = {
    title: 'Mailchimp API retry exhausted',
    text: `Final response: ${JSON.stringify(payload.final_response)}`,
    tags,
    timestamp: Math.floor(Date.now() / 1000)
  }

  const url = `https://event-management-intake.${config.datadogSite}/api/v2/events`
  const fetchFn = config.fetch ?? fetch

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'DD-API-KEY': config.datadogApiKey,
      'DD-APPLICATION-KEY': config.datadogAppKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(event)
  })

  if (!response.ok) {
    throw new Error(`Datadog Events API error: ${response.status} ${response.statusText} at ${url}`)
  }

  return response.json() as Promise<DatadogEventResult>
}

