 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  datadogApiKey: string
  datadogAppKey: string
  datadogSite: string
  fetch?: typeof fetch
}

export interface MailchimpRetryPayload {
  response_status: number
  retry_count: number
  final_response: {
    type: string
    title: string
    status: number
    detail: string
  }
  retry_after_header?: string
}

export interface DatadogEventResult {
  id: string
}

export async function handle(
  payload: MailchimpRetryPayload,
  config: ConnectorConfig
): Promise<DatadogEventResult> {
  if (payload.response_status === undefined || payload.response_status === null) {
    throw new Error('Missing required field: response_status')
  }
  if (payload.retry_count === undefined || payload.retry_count === null) {
    throw new Error('Missing required field: retry_count')
  }
  if (!payload.final_response) {
    throw new Error('Missing required field: final_response')
  }

  const status = payload.response_status === 429 && payload.retry_count >= 3
    ? 'retry_exhausted'
    : 'error'

  const tags = [
    `retry_count:${payload.retry_count}`,
    ...(payload.retry_after_header ? [`retry_after:${payload.retry_after_header}`] : [])
  ]

  const event = {
    title: 'Mailchimp API retry exhausted',
    text: `Final response: ${JSON.stringify(payload.final_response)}`,
    tags,
    timestamp: Math.floor(Date.now() / 1000)
  }

  const url = `https://event-management-intake.${config.datadogSite}/api/v2/events`
  const fetchFn = config.fetch ?? fetch

  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'DD-API-KEY': config.datadogApiKey,
      'DD-APPLICATION-KEY': config.datadogAppKey,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(event)
  })

  if (!response.ok) {
    throw new Error(`Datadog Events API error: ${response.status} ${response.statusText} at ${url}`)
  }

  return response.json() as Promise<DatadogEventResult>
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, MailchimpRetryPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      datadogApiKey: 'test-api-key',
      datadogAppKey: 'test-app-key',
      datadogSite: '{site}',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as MailchimpRetryPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.id).toBe('event-12345')
  })
})

describe('handle', () => {
  it('maps fields correctly and sends expected request body', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/api/v2/events') ? jsonResponse({ id: 'evt-1' }, 201) : jsonResponse({}, 404)
    )
    const config: ConnectorConfig = {
      datadogApiKey: 'api-key',
      datadogAppKey: 'app-key',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 2,
      final_response: {
        type: 'https://mailchimp.com/developer/marketing/docs/errors/',
        title: 'Too Many Requests',
        status: 429,
        detail: 'Rate limit exceeded'
      },
      retry_after_header: '30'
    }
    await handle(payload, config)

    expect(calls.length).toBe(1)
    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://event-management-intake.us5.datadoghq.com/api/v2/events')
    expect(call.json).toEqual({
      title: 'Mailchimp API retry exhausted',
      text: 'Final response: {"type":"https://mailchimp.com/developer/marketing/docs/errors/","title":"Too Many Requests","status":429,"detail":"Rate limit exceeded"}',
      tags: ['retry_count:2', 'retry_after:30'],
      timestamp: expect.any(Number)
    })
  })

  it('includes auth headers DD-API-KEY and DD-APPLICATION-KEY', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'evt-2' }, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'my-api-key',
      datadogAppKey: 'my-app-key',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 1,
      final_response: { type: 't', title: 't', status: 429, detail: 'd' }
    }
    await handle(payload, config)

    const headers = calls[0].headers
    expect(headers.get('DD-API-KEY')).toBe('my-api-key')
    expect(headers.get('DD-APPLICATION-KEY')).toBe('my-app-key')
    expect(headers.get('Content-Type')).toBe('application/json')
  })

  it('omits retry_after tag when header is absent', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'evt-3' }, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'k',
      datadogAppKey: 'k',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 3,
      final_response: { type: 't', title: 't', status: 429, detail: 'd' }
    }
    await handle(payload, config)

    expect(calls[0].json).toEqual(
      expect.objectContaining({ tags: ['retry_count:3'] })
    )
  })

  it('throws on missing response_status', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'k',
      datadogAppKey: 'k',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload = {
      retry_count: 1,
      final_response: { type: 't', title: 't', status: 429, detail: 'd' }
    } as unknown as MailchimpRetryPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: response_status')
  })

  it('throws on missing retry_count', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'k',
      datadogAppKey: 'k',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload = {
      response_status: 429,
      final_response: { type: 't', title: 't', status: 429, detail: 'd' }
    } as unknown as MailchimpRetryPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: retry_count')
  })

  it('throws on missing final_response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'k',
      datadogAppKey: 'k',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload = {
      response_status: 429,
      retry_count: 1
    } as unknown as MailchimpRetryPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: final_response')
  })

  it('throws on non-2xx response from Datadog', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ error: 'unauthorized' }, 401))
    const config: ConnectorConfig = {
      datadogApiKey: 'bad-key',
      datadogAppKey: 'bad-key',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 3,
      final_response: { type: 't', title: 't', status: 429, detail: 'd' }
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Datadog Events API error: 401 Unauthorized at https://event-management-intake.us5.datadoghq.com/api/v2/events'
    )
    expect(calls.length).toBe(1)
  })

  it('sets status to retry_exhausted when response_status is 429 and retry_count >= 3', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'evt-4' }, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'k',
      datadogAppKey: 'k',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload: MailchimpRetryPayload = {
      response_status: 429,
      retry_count: 3,
      final_response: { type: 't', title: 't', status: 429, detail: 'd' }
    }
    await handle(payload, config)

    expect(calls[0].json).toEqual(
      expect.objectContaining({ title: 'Mailchimp API retry exhausted' })
    )
  })

  it('sets status to error when response_status is not 429', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ id: 'evt-5' }, 201))
    const config: ConnectorConfig = {
      datadogApiKey: 'k',
      datadogAppKey: 'k',
      datadogSite: 'us5.datadoghq.com',
      fetch
    }
    const payload: MailchimpRetryPayload = {
      response_status: 500,
      retry_count: 0,
      final_response: { type: 't', title: 'Internal Error', status: 500, detail: 'server error' }
    }
    await handle(payload, config)

    expect(calls[0].json).toEqual(
      expect.objectContaining({ title: 'Mailchimp API retry exhausted' })
    )
  })
})

